import { createSlice } from "@reduxjs/toolkit";
import mongoose from "mongoose";

interface IUser {
  _id?: mongoose.Types.ObjectId;
  name: string;
  email: string;
  password?: string;
  image?: string;

  role: "user" | "vendor" | "admin";

  phone?: string;

  /* ---------------------- VENDOR FIELDS ---------------------- */
  shopName?: string;
  businessAddress?: string;
  gstNumber?: string;

  isApproved?: boolean; // 🌟 vendor can upload products only when approved  

  verificationStatus?: "pending" | "approved" | "rejected";  
  requestedAt?: Date;   // vendor requested approval
  approvedAt?: Date;    // admin approved vendor
  rejectedReason?: string;

  /* ---------------------- ADMIN FIELDS ----------------------- */
  permissions?: string[]; // example: ["manage_vendors","manage_products"]

  createdAt?: Date;
  updatedAt?: Date;
}

interface IuserSlice{
    userData: IUser | null
}

const initialState:IuserSlice = {
    userData:null
}
const userSlice = createSlice({
    name:"user",
    initialState,
    reducers:{
    setUserData:(state,action)=>{
        state.userData = action.payload

    }
    }

    
})

export const {setUserData} = userSlice.actions
export default userSlice.reducer